mkdir -p /hutian/devfix && cd /hutian/devfix && cat > mk.py <<'EOF'
# THROW-AWAY layout fixtures (random numbers) for developing the scripts; never a result.
import numpy as np, pandas as pd
rng=np.random.default_rng(0)
sets=["galaxies","forest","alphafold","gene_expression","census_income","census_healthcare","census_education","plankton","ballots"]
rows=[]
meths=[("labels_z","T1"),("ppi","T1"),("ppipp","T1"),("calib_iso","T1"),("gbm_aipw","T2"),("floor","T1")]
def row(e,d,n,m,t):
    r=1.0 if m=="ppipp" else rng.uniform(.8,1.3); cov=rng.uniform(.93,.96)
    return dict(exp=e,dataset=d,n=n,N=20000,tier=t,method=m,construction="wald",reps=2000,truth=0.5,coverage=cov,cov_lo=cov-.01,cov_hi=cov+.01,width_mean=0.1*r,width_se=.001,ratio_vs_ppipp=r,ratio_lo=r-.03,ratio_hi=r+.03,bias=0,valid=int(rng.random()>.15),sampling="with_replacement")
for d in sets:
  for n in (100,400,1600):
    for m,t in meths: rows.append(row("E3",d,n,m,t))
rows += [row("E5","galaxies",400,m,"T1") for m in ("ppipp","calib_iso")]
rows += [row("E6","census_income",400,m,"T2") for m in ("vec_ppipp_x","gbm_aipw")]
pd.DataFrame(rows).to_csv("cells.csv",index=False)
rows=[]
for i in range(12):
  p=rng.uniform(0,.3); rows.append(dict(dataset="syn_sigmoid",n=100,N=1000,estimator=["ppipp","calib_iso"][i%2],pred_excess_width=p,meas_excess_width=p*rng.uniform(.9,1.1),meas_excess_width_lo=p*.85,meas_excess_width_hi=p*1.15,delta=.1,sigma2_res=.2,reps=2000))
pd.DataFrame(rows).to_csv("prop_check.csv",index=False)
rows=[]
for d in sets[:3]:
  for n in (50,100,200,400,800):
    r=1.2-0.1*np.log2(n/50)
    rows.append(dict(dataset=d,calibrator="isotonic",n=n,N=5000,ratio_vs_ppipp=r,ratio_lo=r-.03,ratio_hi=r+.03,pred_nstar=300,pred_nstar_lo=200,pred_nstar_hi=450,meas_nstar=np.nan))
pd.DataFrame(rows).to_csv("breakeven.csv",index=False)
rows=[]
for d in sets:
  for n in (100,400):
    h=rng.normal(0,.05); g=h+rng.normal(0,.02); rows.append(dict(dataset=d,n=n,calibrator="iso",headroom_hat=h,headroom_hat_lo=h-.02,headroom_hat_hi=h+.02,realised_gain=g,gain_lo=g-.03,gain_hi=g+.03))
pd.DataFrame(rows).to_csv("diagnostic.csv",index=False)
EOF
